begin;

alter table public.rollover_execution_handler_registry drop constraint rollover_execution_handler_registry_mutation_class_check;
alter table public.rollover_execution_handler_registry add constraint rollover_execution_handler_registry_mutation_class_check check(mutation_class in('read_only','contract_domain','roster_domain','taxi_domain','taxi_eligibility_domain','ir_domain','draft_inventory_domain','rookie_authority_domain','rookie_eligibility_domain','dead_cap_domain','team_cap_domain','free_agent_domain','expiring_contract_domain','standings_domain','matchup_domain','playoff_domain','cache_domain','validation_domain','finalization_domain','season_authority_domain'));
alter table public.rollover_execution_handler_registry drop constraint rollover_execution_handler_registry_execution_owner_check;
alter table public.rollover_execution_handler_registry add constraint rollover_execution_handler_registry_execution_owner_check check(execution_owner in('execution','publication'));
insert into public.rollover_execution_handler_registry(operation_code,operation_order,handler_version,input_schema_version,result_schema_version,execution_owner,mutation_class,metadata)
values('PUBLISH_TARGET_SEASON_AUTHORITY',32,1,'phase3b13a-publication-input-v1','phase3b13a-publication-result-v1','publication','season_authority_domain',jsonb_build_object('phase','3B.13A','cap_authority',false,'free_agent_visibility',false,'cutover_lock_release',false,'cache_refresh',false,'external_sync',false));

create table public.rollover_target_season_authority_publications(
 id uuid primary key default gen_random_uuid(),
 rollover_execution_id uuid not null unique references public.rollover_executions(id),
 league_id uuid not null references public.leagues(id),
 closing_season_id uuid not null references public.league_seasons(id),
 target_season_id uuid not null references public.league_seasons(id),
 finalization_id uuid not null unique references public.rollover_executed_unpublished_finalizations(id),
 validation_report_id uuid not null references public.rollover_post_execution_validation_reports(id),
 approval_id uuid not null references public.rollover_execution_plan_approvals(id),
 execution_plan_id uuid not null references public.rollover_execution_plans(id),
 cutover_lock_id uuid not null references public.rollover_execution_locks(id),
 operation_index integer not null check(operation_index=32),
 operation_code text not null check(operation_code='PUBLISH_TARGET_SEASON_AUTHORITY'),
 idempotency_key text not null unique check(length(btrim(idempotency_key))>0),
 request_fingerprint text not null check(request_fingerprint~'^[0-9a-f]{64}$'),
 finalization_fingerprint text not null check(finalization_fingerprint~'^[0-9a-f]{64}$'),
 prepared_artifact_aggregate_hash text not null check(prepared_artifact_aggregate_hash~'^[0-9a-f]{64}$'),
 validation_report_hash text not null check(validation_report_hash~'^[0-9a-f]{64}$'),
 closing_authority_before_hash text not null check(closing_authority_before_hash~'^[0-9a-f]{64}$'),
 target_authority_before_hash text not null check(target_authority_before_hash~'^[0-9a-f]{64}$'),
 closing_authority_after_hash text not null check(closing_authority_after_hash~'^[0-9a-f]{64}$'),
 target_authority_after_hash text not null check(target_authority_after_hash~'^[0-9a-f]{64}$'),
 publication_fingerprint text not null check(publication_fingerprint~'^[0-9a-f]{64}$'),
 published_by uuid not null references auth.users(id),
 published_at timestamptz not null default clock_timestamp(),
 schema_version text not null check(schema_version='phase3b13a-season-authority-publication-v1')
);
alter table public.rollover_target_season_authority_publications enable row level security;
revoke all on public.rollover_target_season_authority_publications from public,anon,authenticated;
grant select,insert on public.rollover_target_season_authority_publications to service_role;
create policy target_season_authority_publication_commissioner_read on public.rollover_target_season_authority_publications for select to authenticated using(exists(select 1 from public.league_memberships m where m.league_id=rollover_target_season_authority_publications.league_id and m.user_id=auth.uid() and m.role='commissioner'));

create or replace function public.guard_phase3b13a_publication_evidence() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin if tg_op in('UPDATE','DELETE') then raise exception 'target_season_authority_publication_immutable';end if;return new;end$$;
create trigger target_season_authority_publication_immutable before update or delete on public.rollover_target_season_authority_publications for each row execute function public.guard_phase3b13a_publication_evidence();

create or replace function public.phase3b13a_prepared_artifact_hash(p_execution_id uuid) returns text language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare x public.rollover_executions%rowtype;src public.league_seasons%rowtype;snap public.rollover_execution_input_snapshots%rowtype;report public.rollover_post_execution_validation_reports%rowtype;material jsonb;
begin
 select * into x from public.rollover_executions where id=p_execution_id;select * into src from public.league_seasons where league_id=x.league_id and season=x.source_season;select * into snap from public.rollover_execution_input_snapshots where rollover_execution_id=x.id;select * into report from public.rollover_post_execution_validation_reports where rollover_execution_id=x.id;
 material:=jsonb_build_object('schema','phase3b12c-prepared-artifacts-v1','snapshot',snap.aggregate_snapshot_fingerprint,'history',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(h)-'created_at'-'completed_at' order by h.id),'[]')) from public.historical_capture_executions h where h.league_season_id=src.id),'owner_outcomes',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(v)-'created_at' order by v.id),'[]')) from public.rollover_owner_option_final_outcomes v where v.rollover_execution_id=x.id),'contracts',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(c)-'created_at' order by c.id),'[]')) from public.contract_seasons c where c.league_id=x.league_id and c.season=x.target_season),'releases',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(r.release_fingerprint order by r.id),'[]')) from public.rollover_contract_releases r where r.rollover_execution_id=x.id),'holds',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(h.creation_fingerprint order by h.id),'[]')) from public.rollover_commissioner_holds h where h.rollover_execution_id=x.id),'roster',(select aggregate_assignment_set_hash from public.rollover_target_roster_assignment_sets where rollover_execution_id=x.id),'taxi',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(d.deterministic_hash order by d.player_id),'[]')) from public.rollover_taxi_eligibility_authorities d where d.rollover_execution_id=x.id),'ir',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(i.deterministic_fingerprint order by i.player_id),'[]')) from public.rollover_ir_reconciliations i where i.rollover_execution_id=x.id),'draft',(select deterministic_class_set_hash from public.rollover_draft_inventory_generations where rollover_execution_id=x.id),'rookie_authority',(select deterministic_authority_fingerprint from public.league_rookie_class_authorities where prepared_execution_id=x.id),'rookie_eligibility',(select eligibility_set_hash from public.prepared_rookie_eligibility_sets where rollover_execution_id=x.id),'dead_cap',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(d.deterministic_fingerprint order by d.id),'[]')) from public.rollover_dead_cap_obligations d where d.rollover_execution_id=x.id),'cap',(select aggregate_cap_set_hash from public.prepared_team_cap_sets where rollover_execution_id=x.id),'free_agent',(select aggregate_set_hash from public.prepared_free_agent_eligibility_sets where rollover_execution_id=x.id),'expiring',(select aggregate_set_hash from public.prepared_expiring_contract_sets where rollover_execution_id=x.id),'standings',(select aggregate_standings_hash from public.prepared_target_standings_sets where rollover_execution_id=x.id),'matchups',(select aggregate_matchup_hash from public.prepared_target_matchup_sets where rollover_execution_id=x.id),'playoffs',(select aggregate_structure_hash from public.prepared_target_playoff_structures where rollover_execution_id=x.id),'cache',(select aggregate_manifest_hash from public.season_cache_invalidation_manifests where rollover_execution_id=x.id),'validation',report.aggregate_validation_hash);
 return public.rollover_material_fingerprint(material);
end$$;

create or replace function public.publish_target_season_authority_phase3b13a_private(p_request jsonb,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare x public.rollover_executions%rowtype;f public.rollover_executed_unpublished_finalizations%rowtype;r public.rollover_post_execution_validation_reports%rowtype;a public.rollover_execution_plan_approvals%rowtype;p public.rollover_execution_plans%rowtype;l public.rollover_execution_locks%rowtype;src public.league_seasons%rowtype;tgt public.league_seasons%rowtype;prior public.rollover_target_season_authority_publications%rowtype;publishedrow public.rollover_target_season_authority_publications%rowtype;k text:=nullif(btrim(p_request->>'idempotency_key'),'');reqfp text;artifacthash text;srcbefore text;tgtbefore text;srcafter text;tgtafter text;pubfp text;material jsonb;
begin
 if p_actor is null or k is null then raise exception 'authenticated actor and idempotency key required';end if;
 if nullif(p_request->>'rollover_execution_id','') is null or nullif(p_request->>'finalization_id','') is null or nullif(p_request->>'expected_finalization_fingerprint','') is null or nullif(p_request->>'expected_artifact_hash','') is null or nullif(p_request->>'approval_id','') is null or nullif(p_request->>'execution_plan_id','') is null or nullif(p_request->>'expected_plan_fingerprint','') is null then raise exception 'complete publication assertions required';end if;
 perform pg_advisory_xact_lock(hashtextextended('phase3b13a:'||(p_request->>'rollover_execution_id'),0));
 select * into x from public.rollover_executions where id=(p_request->>'rollover_execution_id')::uuid for update;if x.id is null then raise exception 'publication execution not found';end if;perform public.require_commissioner_authority(x.league_id);
 material:=jsonb_build_object('operation','PUBLISH_TARGET_SEASON_AUTHORITY','execution',x.id,'league',x.league_id,'request',p_request-'idempotency_key','actor',p_actor);reqfp:=public.rollover_material_fingerprint(material);
 select * into prior from public.rollover_target_season_authority_publications where rollover_execution_id=x.id for share;
 if found then if prior.idempotency_key<>k or prior.request_fingerprint<>reqfp then raise exception 'incompatible operation 32 publication result exists';end if;return jsonb_build_object('success',true,'idempotent',true,'publication_id',prior.id,'execution_id',x.id,'operation_index',32,'operation_code','PUBLISH_TARGET_SEASON_AUTHORITY','source_status','completed','target_status','active','cutover_lock_active',true,'cap_authority_activated',false,'free_agent_visibility_enabled',false,'cache_refreshed',false,'external_sync_performed',false);end if;
 if x.status<>'executed_unpublished' then raise exception 'publication requires executed_unpublished';end if;
 select * into f from public.rollover_executed_unpublished_finalizations where id=(p_request->>'finalization_id')::uuid and rollover_execution_id=x.id for share;if f.id is null or f.finalization_status<>'executed_unpublished' or f.deterministic_finalization_fingerprint<>p_request->>'expected_finalization_fingerprint' or f.prepared_artifact_aggregate_hash<>p_request->>'expected_artifact_hash' or not f.publication_eligible or f.publication_blocker_count<>0 then raise exception 'finalization is absent stale or publication blocked';end if;
 select * into r from public.rollover_post_execution_validation_reports where id=f.validation_report_id and rollover_execution_id=x.id for share;if r.id is null or r.aggregate_validation_hash<>f.validation_report_hash or r.execution_failure_count<>0 or not r.publication_eligible or r.publication_blocker_count<>0 or r.actual_check_count<>r.expected_check_count or exists(select 1 from public.rollover_post_execution_validation_checks where report_id=r.id and status='execution_failure') then raise exception 'operation 30 validation evidence invalid';end if;
 select * into p from public.rollover_execution_plans where id=(p_request->>'execution_plan_id')::uuid and id=f.execution_plan_id and rollover_execution_id=x.id for share;select * into a from public.rollover_execution_plan_approvals where id=(p_request->>'approval_id')::uuid and id=f.approval_id and execution_plan_id=p.id and rollover_execution_id=x.id for share;if p.id is null or a.id is null or p.plan_status<>'approved_for_execution' or not p.approved_for_execution or a.approval_status<>'approved' or p.plan_fingerprint<>p_request->>'expected_plan_fingerprint' or p.plan_fingerprint<>a.plan_fingerprint or p.plan_fingerprint<>x.execution_plan_fingerprint then raise exception 'publication plan or approval stale';end if;
 select * into l from public.rollover_execution_locks where id=f.cutover_lock_id and rollover_execution_id=x.id and approval_id=a.id and execution_plan_id=p.id and lock_type='cutover' and lock_scope='rollover_global' and status='active' for update;if l.id is null then raise exception 'active matching cutover lock required';end if;
 select * into src from public.league_seasons where id=f.closing_season_id and league_id=x.league_id and season=x.source_season for update;select * into tgt from public.league_seasons where id=f.target_season_id and league_id=x.league_id and season=x.target_season for update;if src.id is null or not src.is_active or src.status<>'active' or tgt.id is null or tgt.is_active or tgt.status<>'scheduled' or (select count(*) from public.league_seasons where league_id=x.league_id and is_active)<>1 then raise exception 'canonical season authority changed after finalization';end if;
 artifacthash:=public.phase3b13a_prepared_artifact_hash(x.id);if artifacthash<>f.prepared_artifact_aggregate_hash or artifacthash<>p_request->>'expected_artifact_hash' then raise exception 'prepared artifact source changed after finalization';end if;
 if exists(select 1 from public.rollover_execution_operation_results where rollover_execution_id=x.id and operation_index>=32) then raise exception 'incompatible operation 32-36 execution result exists';end if;
 if not exists(select 1 from public.season_cache_invalidation_manifests h where h.rollover_execution_id=x.id and h.status='prepared' and h.published_at is null and h.completed_at is null) or exists(select 1 from public.season_cache_invalidation_entries e join public.season_cache_invalidation_manifests h on h.id=e.manifest_id where h.rollover_execution_id=x.id and ((e.required_action in('rebuild_before_publication','rebuild_during_publication','external_sync_required') and e.completion_status<>'pending') or e.rebuilt_at is not null)) then raise exception 'cache or external publication work is not pending';end if;
 if not exists(select 1 from public.season_cache_invalidation_entries e join public.season_cache_invalidation_manifests h on h.id=e.manifest_id where h.rollover_execution_id=x.id and e.required_action='external_sync_required' and e.completion_status='pending') then raise exception 'external synchronization pending evidence missing';end if;
 if not exists(select 1 from public.prepared_team_cap_sets where rollover_execution_id=x.id and status='prepared_unpublished') or exists(select 1 from public.prepared_team_caps c join public.prepared_team_cap_sets s on s.id=c.cap_set_id where s.rollover_execution_id=x.id and c.published_at is not null) or exists(select 1 from public.cap_season_authorities where league_id=x.league_id and season=x.target_season and status='authoritative') then raise exception 'target cap authority is not exclusively prepared';end if;
 if not exists(select 1 from public.prepared_free_agent_eligibility_sets where rollover_execution_id=x.id and status='prepared') or exists(select 1 from public.free_agent_publications where league_id=x.league_id and season=x.target_season and(publication_status='published' or acquisition_status='eligible')) then raise exception 'target free-agent visibility is not disabled';end if;
 srcbefore:=public.rollover_material_fingerprint(jsonb_build_object('id',src.id,'league',src.league_id,'season',src.season,'status',src.status,'active',src.is_active));tgtbefore:=public.rollover_material_fingerprint(jsonb_build_object('id',tgt.id,'league',tgt.league_id,'season',tgt.season,'status',tgt.status,'active',tgt.is_active));
 update public.league_seasons set is_active=false,status='completed' where id=src.id;update public.league_seasons set is_active=true,status='active' where id=tgt.id;
 srcafter:=public.rollover_material_fingerprint(jsonb_build_object('id',src.id,'league',src.league_id,'season',src.season,'status','completed','active',false));tgtafter:=public.rollover_material_fingerprint(jsonb_build_object('id',tgt.id,'league',tgt.league_id,'season',tgt.season,'status','active','active',true));pubfp:=public.rollover_material_fingerprint(jsonb_build_object('schema','phase3b13a-season-authority-publication-v1','execution',x.id,'finalization',f.deterministic_finalization_fingerprint,'artifacts',artifacthash,'validation',r.aggregate_validation_hash,'source_before',srcbefore,'target_before',tgtbefore,'source_after',srcafter,'target_after',tgtafter,'lock',l.id));
 insert into public.rollover_target_season_authority_publications(rollover_execution_id,league_id,closing_season_id,target_season_id,finalization_id,validation_report_id,approval_id,execution_plan_id,cutover_lock_id,operation_index,operation_code,idempotency_key,request_fingerprint,finalization_fingerprint,prepared_artifact_aggregate_hash,validation_report_hash,closing_authority_before_hash,target_authority_before_hash,closing_authority_after_hash,target_authority_after_hash,publication_fingerprint,published_by,schema_version) values(x.id,x.league_id,src.id,tgt.id,f.id,r.id,a.id,p.id,l.id,32,'PUBLISH_TARGET_SEASON_AUTHORITY',k,reqfp,f.deterministic_finalization_fingerprint,artifacthash,r.aggregate_validation_hash,srcbefore,tgtbefore,srcafter,tgtafter,pubfp,p_actor,'phase3b13a-season-authority-publication-v1') returning * into publishedrow;
 return jsonb_build_object('success',true,'idempotent',false,'publication_id',publishedrow.id,'execution_id',x.id,'operation_index',32,'operation_code','PUBLISH_TARGET_SEASON_AUTHORITY','source_status','completed','target_status','active','publication_fingerprint',pubfp,'cutover_lock_active',true,'cap_authority_activated',false,'free_agent_visibility_enabled',false,'cache_refreshed',false,'external_sync_performed',false);
end$$;

create or replace function public.publish_target_season_authority_authenticated(p_request jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare actor uuid:=public.require_authenticated_user();begin if p_request?'actor_user_id' or p_request?'published_by' or p_request?'publication_eligible' or p_request?'publication_blocker_count' or p_request?'season_status' or p_request?'cap_authority' or p_request?'free_agent_visibility' or p_request?'release_cutover' or p_request?'cache_refresh' or p_request?'external_sync' then raise exception 'actor or publication material spoofing forbidden';end if;return public.publish_target_season_authority_phase3b13a_private(p_request,actor);end$$;

revoke all on function public.guard_phase3b13a_publication_evidence(),public.phase3b13a_prepared_artifact_hash(uuid),public.publish_target_season_authority_phase3b13a_private(jsonb,uuid),public.publish_target_season_authority_authenticated(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.publish_target_season_authority_authenticated(jsonb) to authenticated;

commit;
